import SwiftUI
import AVKit

struct VideoPlayerView: View {
    let video: Video
    @Binding var isPresented: Bool
    @State private var player: AVPlayer?

    var body: some View {
        ZStack {
            Color.black.ignoresSafeArea()

            if let player = player {
                VideoPlayer(player: player)
                    .ignoresSafeArea()
                    .onAppear {
                        player.play()
                    }
                    .onDisappear {
                        player.pause()
                    }
            } else {
                VStack(spacing: 20) {
                    ProgressView()
                        .progressViewStyle(CircularProgressViewStyle(tint: .white))
                        .scaleEffect(1.5)

                    Text("動画を読み込んでいます...")
                        .foregroundColor(.white)
                        .font(.subheadline)
                }
            }

            // 閉じるボタン
            VStack {
                HStack {
                    Button(action: {
                        isPresented = false
                    }) {
                        Image(systemName: "xmark.circle.fill")
                            .font(.system(size: 30))
                            .foregroundColor(.white)
                            .shadow(color: .black.opacity(0.5), radius: 4, x: 0, y: 2)
                    }
                    .padding()

                    Spacer()
                }
                Spacer()
            }
        }
        .onAppear {
            setupPlayer()
        }
        .onDisappear {
            player?.pause()
            player = nil
        }
    }

    private func setupPlayer() {
        guard let videoURL = Bundle.main.url(
            forResource: "videos/\(video.filename.components(separatedBy: ".").dropLast().joined(separator: "."))",
            withExtension: video.filename.components(separatedBy: ".").last
        ) else {
            print("Video file not found: \(video.filename)")
            return
        }

        player = AVPlayer(url: videoURL)

        // 動画が終了したら最初に戻る
        NotificationCenter.default.addObserver(
            forName: .AVPlayerItemDidPlayToEndTime,
            object: player?.currentItem,
            queue: .main
        ) { _ in
            player?.seek(to: .zero)
            player?.play()
        }
    }
}

